# In starlette/routing.py, ensure the Mount class properly handles path matching

class Mount:
    def __init__(
        self,
        path: str,
        app: ASGIApp,
        name: Optional[str] = None,
    ) -> None:
        self.path = path.rstrip("/")
        self.app = app
        self.name = name

    def matches(self, scope: Scope) -> Tuple[Match, Scope]:
        if scope["type"] == "http":
            path = scope["path"]
            if path.startswith(self.path):
                # Ensure we handle the root path case correctly
                if path == self.path:
                    matched_path = self.path
                    remaining_path = "/"
                else:
                    matched_path = self.path
                    remaining_path = path[len(self.path) :]
                    if not remaining_path.startswith("/"):
                        remaining_path = "/" + remaining_path

                child_scope = dict(scope)
                child_scope["path"] = remaining_path
                child_scope["root_path"] = scope.get("root_path", "") + matched_path
                return Match.FULL, child_scope

        return Match.NONE, {}
